package com.pixelempire.clicker;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

public final class ReleaseArt {
    private ReleaseArt() {}
    private static final String WORLD = "";
    public static Bitmap world(){byte[] b=Base64.decode(WORLD,Base64.DEFAULT);return BitmapFactory.decodeByteArray(b,0,b.length);}
}
